// @vitest-environment node
import { describe, expect, it, vi } from 'vitest';

vi.mock('./wasm', async () => {
    const { readFileSync: read } = await import('node:fs');
    const dir = new URL('../wasm-pkg/', import.meta.url);
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore — generated by scripts/build-wasm.sh (wasm-bindgen)
    const glue = await import('../wasm-pkg/anonymiser_wasm');
    glue.initSync({ module: read(new URL('anonymiser_wasm_bg.wasm', dir)) });
    return { ...glue, ensureWasm: async () => {} };
});

import { measureAnonymity, suppressForRelease } from './anonymity';
import type { ColumnPolicy } from '../types/policy';

const HEADERS = ['id', 'dob', 'city'];
const ROWS = [
    [1, '1980-01-01', 'Bristol'],
    [2, '1980-06-30', 'Bristol'],
    [3, '1980-12-11', 'Bristol'],
    [4, '1990-02-02', 'Leeds'],
];
const YEAR: Record<number, ColumnPolicy> = { 0: { type: 'redact' }, 1: { type: 'year' } };

describe('measureAnonymity', () => {
    it('measures the post-policy values: year generalisation merges the dates', async () => {
        const raw = await measureAnonymity(ROWS, HEADERS, [], {}, {}, [1, 2], 3);
        expect(raw.report.min_group).toBe(1);
        const gen = await measureAnonymity(ROWS, HEADERS, [], YEAR, {}, [1, 2], 3);
        expect(gen.report.min_group).toBe(1);
        expect(gen.report.rows_below_k).toBe(1);
        expect(gen.report.satisfied).toBe(false);
        expect(gen.claim).toContain('Not k-anonymous at k=3');
        expect(gen.claim).toContain('dob, city');
    });
});

describe('suppressForRelease', () => {
    it('cells: suppresses the small group, keeps types, and passes', async () => {
        const { data: post } = { data: ROWS.map((r) => [r[0], String(r[1]).slice(0, 4), r[2]]) };
        const { data, check } = await suppressForRelease(post, HEADERS, [1, 2], 3, 'cells');
        expect(data[3]).toEqual([4, '*', '*']);
        expect(data[0]).toEqual([1, '1980', 'Bristol']);
        expect(typeof data[0][0]).toBe('number');
        expect(check.passed).toBe(true);
        expect(check.report.min_group).toBe(3);
        expect(check.before.rows_below_k).toBe(1);
        expect(check.suppression.cells_suppressed).toBe(2);
    });

    it('rows: drops the small group in order', async () => {
        const post = ROWS.map((r) => [r[0], String(r[1]).slice(0, 4), r[2]]);
        const { data, check } = await suppressForRelease(post, HEADERS, [1, 2], 3, 'rows');
        expect(data.map((r) => r[0])).toEqual([1, 2, 3]);
        expect(check.suppression.rows_dropped).toBe(1);
        expect(check.passed).toBe(true);
    });

    it('does not pass when no row can reach k', async () => {
        const { check } = await suppressForRelease(ROWS, HEADERS, [1], 3, 'cells');
        expect(check.passed).toBe(false);
        expect(check.report.rows).toBe(0);
    });
});
